def check(v,s,path):
 t=s.get(\"type\"); types={\"object\":dict,\"array\":list,\"string\":str,\"integer\":int,\"number\":(int,float),\"boolean\":bool}
 if t: assert isinstance(v,types[t]),(path,t,type(v))
 if \"const\" in s: assert v==s[\"const\"],path
 if \"enum\" in s: assert v in s[\"enum\"],path
 if isinstance(v,dict):
  assert all(k in v for k in s.get(\"required\",[])),path
  props=s.get(\"properties\",{})
  if s.get(\"additionalProperties\") is False: assert set(v)<=set(props),(path,set(v)-set(props))
  for k,val in v.items():
   if k in props:check(val,props[k],path+\".\"+k)
 if isinstance(v,list):
  assert len(v)>=s.get(\"minItems\",0),path
  for i,item in enumerate(v):check(item,s.get(\"items\",{}),path+\"[\"+str(i)+\"]\")
 if isinstance(v,str):assert len(v)>=s.get(\"minLength\",0),path
check(p[\"study\"],schema,\"study\")
assert p[\"study\"][\"protocol_ref\"]==r[\"required_study_protocol_ref\"]
allowed=set(r[\"context\"][\"allowed_observation_ids\"])
assert set(p[\"study\"][\"evidence_refs\"])<=allowed
assert p[\"parent_trial\"] in allowed
assert len(p[\"variants\"]) in range(1,5)
assert len({v[\"name\"] for v in p[\"variants\"]})==len(p[\"variants\"])
assert len({v[\"file\"] for v in p[\"variants\"]})==len(p[\"variants\"])
assert any(v[\"role\"]==\"candidate\" for v in p[\"variants\"])
assert r[\"context\"][\"previous_runtime_error\"] is None
assert 7043.73+12000+24000 < r[\"context\"][\"remaining_seconds\"]
print(\"Runtime study schema, protocol, evidence IDs, parent, variant suite and reserves passed; remaining\",r[\"context\"][\"remaining_seconds\"])
'"

